CREATE OR REPLACE FUNCTION public.smart_alert_limit_open() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' AND NEW.kind IS NOT NULL AND NEW.status='open' THEN PERFORM pg_advisory_xact_lock(hashtext('smart-alert:'||NEW.tenant_id::text));IF (SELECT count(*) FROM alert_events WHERE tenant_id=NEW.tenant_id AND status='open' AND kind IS NOT NULL AND id<>NEW.id)>=10 THEN NEW.status:='summary';END IF;END IF;RETURN NEW;END $$;